  constraint session_timers_pkey primary key (id),
  constraint session_timers_duration_sec_check check (duration_sec > 0),
  constraint session_timers_status_check check (status in ('running', 'paused', 'done', 'cancelled'))
);
comment on table public.session_timers is 'Timers in a cooking session; mirrored to local notifications on the phone. Retention: With session.';

-- session_events (V1, Cooking): Append-only log of everything that happened while cooking (touch and voice). No audio.
create table public.session_events (
  id bigint generated always as identity not null,
  household_id uuid not null,
  session_id uuid not null,
  event_type text not null,
  step_no smallint,
  channel text default 'touch' not null,
  utterance text,
  payload jsonb default '{}'::jsonb not null,
  latency_ms integer,
  created_at timestamptz default now() not null,
  constraint session_events_pkey primary key (id),
  constraint session_events_event_type_check check (event_type in ('step_next', 'step_back', 'repeat', 'question', 'answer', 'substitution', 'modification', 'rescue', 'photo_checkpoint', 'timer_set', 'timer_done', 'whistle', 'barge_in', 'tool_call', 'fast_path', 'error')),
  constraint session_events_channel_check check (channel in ('touch', 'voice'))
);
comment on table public.session_events is 'Append-only log of everything that happened while cooking (touch and voice). No audio. Retention: Utterance text 30 days (if consented); rest 2 years.';

-- photo_checkpoints (V1, Cooking): Photos the user shows at a step and the AI's assessment.
create table public.photo_checkpoints (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  session_id uuid not null,
  step_no smallint not null,
  image_path text not null,
  assessment text,
  verdict text,
  confidence numeric(3,2),
  model text,
  created_at timestamptz default now() not null,
  constraint photo_checkpoints_pkey primary key (id),
  constraint photo_checkpoints_verdict_check check (verdict in ('looks_right', 'needs_more', 'overdone', 'unsafe', 'unsure')),
  constraint photo_checkpoints_confidence_check check (confidence between 0 and 1)
);
comment on table public.photo_checkpoints is 'Photos the user shows at a step and the AI''s assessment. Retention: Images 90 days.';

-- meal_feedback (V1, Learning): Per-member feedback after a cooking session.
create table public.meal_feedback (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  session_id uuid not null,
  member_id uuid not null,
  rating text not null,
  tags text[] default '{}' not null,
  comment text,
  make_again boolean,
  created_at timestamptz default now() not null,
  constraint meal_feedback_pkey primary key (id),
  constraint meal_feedback_session_id_member_id_key unique (session_id, member_id),
  constraint meal_feedback_rating_check check (rating in ('loved', 'good', 'meh', 'bad'))
);
comment on table public.meal_feedback is 'Per-member feedback after a cooking session. Retention: Permanent.';

-- memories (V1, Learning): What Cookmate has learned, with scope, source, confidence and provenance. Users can edit, keep or forget each one.
create table public.memories (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  member_id uuid,
  statement text not null,
  category text not null,
  scope text default 'permanent' not null,
  polarity smallint default 0 not null,
  subject_ingredient_id uuid,
  subject_recipe_id uuid,
  attributes jsonb default '{}'::jsonb not null,
  confidence numeric(3,2) default 0.60 not null,
  source text not null,
  evidence_count integer default 1 not null,
  provenance jsonb default '{}'::jsonb not null,
  status text default 'active' not null,
  superseded_by uuid,
  expires_at timestamptz,
  last_confirmed_at timestamptz,
  created_at timestamptz default now() not null,
  updated_at timestamptz default now() not null,
  constraint memories_pkey primary key (id),
  constraint memories_category_check check (category in ('taste', 'ingredient', 'technique', 'routine', 'household', 'diet', 'equipment', 'other')),
  constraint memories_scope_check check (scope in ('permanent', 'temporary')),
  constraint memories_polarity_check check (polarity between -1 and 1),
  constraint memories_confidence_check check (confidence between 0 and 1),
  constraint memories_source_check check (source in ('explicit', 'observed', 'correction', 'onboarding')),
  constraint memories_status_check check (status in ('active', 'forgotten', 'superseded', 'expired'))
);
comment on table public.memories is 'What Cookmate has learned, with scope, source, confidence and provenance. Users can edit, keep or forget each one. Retention: Until forgotten; forgotten rows hard-deleted after 30 days.';

-- taste_profiles (V1, Learning): Current taste dials per member, updated from feedback and memories.
create table public.taste_profiles (
  member_id uuid not null,
  household_id uuid not null,
  spice smallint default 3 not null,
  sweetness smallint default 3 not null,
  richness smallint default 3 not null,
  sourness smallint default 3 not null,
  textures text[] default '{}' not null,
  preferred_cuisines text[] default '{}' not null,
  max_time_min smallint,
  difficulty_pref smallint,
  updated_at timestamptz default now() not null,
  constraint taste_profiles_pkey primary key (member_id),
  constraint taste_profiles_spice_check check (spice between 1 and 5),
  constraint taste_profiles_sweetness_check check (sweetness between 1 and 5),
  constraint taste_profiles_richness_check check (richness between 1 and 5),
  constraint taste_profiles_sourness_check check (sourness between 1 and 5),
  constraint taste_profiles_difficulty_pref_check check (difficulty_pref between 1 and 5)
);
comment on table public.taste_profiles is 'Current taste dials per member, updated from feedback and memories. Retention: Until member removed.';

-- ingredient_preferences (V1, Learning): Likes and dislikes per member and ingredient.
create table public.ingredient_preferences (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  member_id uuid not null,
  ingredient_id uuid not null,
  preference smallint not null,
  confidence numeric(3,2) default 0.60 not null,
  source text not null,
  updated_at timestamptz default now() not null,
  constraint ingredient_preferences_pkey primary key (id),
  constraint ingredient_preferences_member_id_ingredient_id_key unique (member_id, ingredient_id),
  constraint ingredient_preferences_preference_check check (preference between -2 and 2),
  constraint ingredient_preferences_confidence_check check (confidence between 0 and 1),
  constraint ingredient_preferences_source_check check (source in ('explicit', 'observed', 'correction', 'onboarding'))
);
comment on table public.ingredient_preferences is 'Likes and dislikes per member and ingredient. Retention: Until member removed.';

-- member_skills (V2, Learning): Technique ladder progress per member (V2).
create table public.member_skills (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  member_id uuid not null,
  technique_id uuid not null,
  level smallint default 0 not null,
  times_practiced integer default 0 not null,
  last_practiced_at timestamptz,
  constraint member_skills_pkey primary key (id),
  constraint member_skills_member_id_technique_id_key unique (member_id, technique_id),
  constraint member_skills_level_check check (level between 0 and 5)
);
comment on table public.member_skills is 'Technique ladder progress per member (V2). Retention: Until member removed.';

-- nutrition_weekly (V1.5, Health): Weekly plate summary by food group, computed from sessions (V1.5).
create table public.nutrition_weekly (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  member_id uuid,
  week_start date not null,
  food_groups jsonb default '{}'::jsonb not null,
  nudges jsonb default '[]'::jsonb not null,
  computed_at timestamptz default now() not null,
  constraint nutrition_weekly_pkey primary key (id),
  constraint nutrition_weekly_household_id_member_id_week_start_key unique (household_id, member_id, week_start)
);
comment on table public.nutrition_weekly is 'Weekly plate summary by food group, computed from sessions (V1.5). Retention: 1 year.';

-- shopping_lists (V1, Shopping): Shopping lists per household.
create table public.shopping_lists (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  name text default 'Main' not null,
  status text default 'active' not null,
  created_at timestamptz default now() not null,
  constraint shopping_lists_pkey primary key (id),
  constraint shopping_lists_status_check check (status in ('active', 'archived'))
);
comment on table public.shopping_lists is 'Shopping lists per household. Retention: Archived lists 1 year.';

-- shopping_list_items (V1, Shopping): Items to buy, with why they are on the list.
create table public.shopping_list_items (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  list_id uuid not null,
  ingredient_id uuid,
  product_id uuid,
  display_name text not null,
  quantity numeric,
  unit text,
  reason text default 'manual' not null,
  recipe_id uuid,
  status text default 'needed' not null,
  added_by uuid,
  created_at timestamptz default now() not null,
  bought_at timestamptz,
  constraint shopping_list_items_pkey primary key (id),
  constraint shopping_list_items_reason_check check (reason in ('recipe_missing', 'running_low', 'predicted', 'manual', 'voice')),
  constraint shopping_list_items_status_check check (status in ('needed', 'in_cart', 'bought', 'removed'))
);
comment on table public.shopping_list_items is 'Items to buy, with why they are on the list. Retention: 1 year.';

-- purchase_patterns (V2, Shopping): Learned buying rhythm per ingredient for predictive restocking (V2).
create table public.purchase_patterns (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  ingredient_id uuid not null,
  avg_interval_days numeric,
  avg_quantity numeric,
  unit text,
  preferred_product_id uuid,
  preferred_provider_id uuid,
  last_purchased_at timestamptz,
  next_predicted_at timestamptz,
  sample_count integer default 0 not null,
  updated_at timestamptz default now() not null,
  constraint purchase_patterns_pkey primary key (id),
  constraint purchase_patterns_household_id_ingredient_id_key unique (household_id, ingredient_id)
);
comment on table public.purchase_patterns is 'Learned buying rhythm per ingredient for predictive restocking (V2). Retention: Rolling.';

-- grocery_providers (V2, Shopping): Grocery providers with official integrations (V2).
create table public.grocery_providers (
  id uuid default gen_random_uuid() not null,
  slug text not null,
  name text not null,
  integration_type text not null,
  status text default 'planned' not null,
  regions text[] default '{}' not null,
  created_at timestamptz default now() not null,
  constraint grocery_providers_pkey primary key (id),
  constraint grocery_providers_slug_key unique (slug),
  constraint grocery_providers_integration_type_check check (integration_type in ('official_api', 'partner_feed', 'deeplink')),
  constraint grocery_providers_status_check check (status in ('planned', 'active', 'paused'))
);
comment on table public.grocery_providers is 'Grocery providers with official integrations (V2). Retention: Permanent.';

-- provider_connections (V2, Shopping): A household's linked provider account; tokens live in Supabase Vault, never in this table (V2).
create table public.provider_connections (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  provider_id uuid not null,
  status text default 'connected' not null,
  external_account_ref text,
  vault_secret_id uuid,
  connected_at timestamptz default now() not null,
  constraint provider_connections_pkey primary key (id),
  constraint provider_connections_household_id_provider_id_key unique (household_id, provider_id),
  constraint provider_connections_status_check check (status in ('connected', 'expired', 'revoked'))
);
comment on table public.provider_connections is 'A household''s linked provider account; tokens live in Supabase Vault, never in this table (V2). Retention: Until disconnected.';

-- carts (V2, Shopping): Provider carts built by the grocery agent. Nothing is placed without approval.
create table public.carts (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  provider_id uuid not null,
  status text default 'draft' not null,
  subtotal_inr numeric(10,2),
  fees_inr numeric(10,2),
  total_inr numeric(10,2),
  approved_by uuid,
  approved_at timestamptz,
  external_order_id text,
  placed_at timestamptz,
  created_at timestamptz default now() not null,
  constraint carts_pkey primary key (id),
  constraint carts_status_check check (status in ('draft', 'awaiting_approval', 'approved', 'placed', 'failed', 'cancelled'))
);
comment on table public.carts is 'Provider carts built by the grocery agent. Nothing is placed without approval. Retention: 2 years.';

-- cart_items (V2, Shopping): Lines in a provider cart (V2).
create table public.cart_items (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  cart_id uuid not null,
  list_item_id uuid,
  provider_product_ref text not null,
  name text not null,
  quantity numeric not null,
  unit_price_inr numeric(10,2),
  line_total_inr numeric(10,2),
  constraint cart_items_pkey primary key (id)
);
comment on table public.cart_items is 'Lines in a provider cart (V2). Retention: With cart.';

-- devices (V1, Platform): Phones signed in to a member, with push tokens.
create table public.devices (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  member_id uuid not null,
  platform text not null,
  push_token text,
  app_version text,
  locale text,
  last_seen_at timestamptz default now() not null,
  created_at timestamptz default now() not null,
  constraint devices_pkey primary key (id),
  constraint devices_push_token_key unique (push_token),
  constraint devices_platform_check check (platform in ('android', 'ios'))
);
comment on table public.devices is 'Phones signed in to a member, with push tokens. Retention: Removed 90 days after last seen.';

-- notifications (V1, Platform): Scheduled and sent notifications; enforces the one-proactive-nudge-a-day cap.
create table public.notifications (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  member_id uuid not null,
  type text not null,
  payload jsonb default '{}'::jsonb not null,
  channel text default 'push' not null,
  scheduled_for timestamptz not null,
  sent_at timestamptz,
  opened_at timestamptz,
  status text default 'scheduled' not null,
  created_at timestamptz default now() not null,
  constraint notifications_pkey primary key (id),
  constraint notifications_type_check check (type in ('daily_pick', 'use_soon', 'leftover', 'restock', 'timer', 'system')),
  constraint notifications_channel_check check (channel in ('push', 'whatsapp', 'in_app')),
  constraint notifications_status_check check (status in ('scheduled', 'sent', 'failed', 'cancelled', 'suppressed'))
);
comment on table public.notifications is 'Scheduled and sent notifications; enforces the one-proactive-nudge-a-day cap. Retention: 90 days.';

-- channel_identities (V2, Platform): WhatsApp or phone identities linked to a member (V2). Numbers stored hashed.
create table public.channel_identities (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  member_id uuid not null,
  channel text not null,
  external_id_hash text not null,
  verified_at timestamptz,
  created_at timestamptz default now() not null,
  constraint channel_identities_pkey primary key (id),
  constraint channel_identities_channel_external_id_hash_key unique (channel, external_id_hash),
  constraint channel_identities_channel_check check (channel in ('whatsapp', 'phone'))
);
comment on table public.channel_identities is 'WhatsApp or phone identities linked to a member (V2). Numbers stored hashed. Retention: Until unlinked.';

-- voice_sessions (V1, Telemetry): One row per Voice Cook connection: usage, latency and cost. No audio, no transcript.
create table public.voice_sessions (
  id uuid default gen_random_uuid() not null,
  household_id uuid not null,
  member_id uuid,
  cooking_session_id uuid,
  room_name text not null,
  channel text default 'app' not null,
  language_detected text,
  started_at timestamptz default now() not null,
  ended_at timestamptz,
  end_reason text,
  turns integer default 0 not null,
  fast_path_turns integer default 0 not null,
  stt_seconds numeric default 0 not null,
  tts_characters integer default 0 not null,
  tts_cached_characters integer default 0 not null,
  llm_input_tokens integer default 0 not null,
  llm_cached_tokens integer default 0 not null,
  llm_output_tokens integer default 0 not null,
  p50_latency_ms integer,
  p95_latency_ms integer,
  cost_inr numeric(8,2),
  constraint voice_sessions_pkey primary key (id),
  constraint voice_sessions_channel_check check (channel in ('app', 'whatsapp', 'phone'))
);
comment on table public.voice_sessions is 'One row per Voice Cook connection: usage, latency and cost. No audio, no transcript. Retention: 2 years.';

-- ai_requests (V1, Telemetry): Log of every model call made by Edge Functions and the agent, for cost and quality monitoring.
create table public.ai_requests (
  id bigint generated always as identity not null,
  household_id uuid,
  task text not null,
  model text not null,
  prompt_version text not null,
  input_tokens integer,
  cached_tokens integer,
  output_tokens integer,
  latency_ms integer,
  status text not null,
  error text,
  created_at timestamptz default now() not null,
  constraint ai_requests_pkey primary key (id),
  constraint ai_requests_status_check check (status in ('ok', 'error', 'timeout', 'refused', 'invalid_output'))
);
comment on table public.ai_requests is 'Log of every model call made by Edge Functions and the agent, for cost and quality monitoring. Retention: 90 days.';

