-- Row-level security helpers
create or replace function private.is_household_member(p_household uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.household_members m
    where m.household_id = p_household
      and m.user_id = (select auth.uid())
      and m.status = 'active'
  );
$$;

create or replace function private.has_household_role(p_household uuid, p_roles text[]) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.household_members m
    where m.household_id = p_household
      and m.user_id = (select auth.uid())
      and m.status = 'active'
      and m.role = any (p_roles)
  );
$$;

revoke all on all functions in schema private from public;
grant execute on function private.is_household_member(uuid) to authenticated, service_role;
grant execute on function private.has_household_role(uuid, text[]) to authenticated, service_role;

-- Row-level security policies
alter table public.profiles enable row level security;
create policy profiles_own_select on public.profiles for select to authenticated
  using (id = (select auth.uid()));
create policy profiles_own_insert on public.profiles for insert to authenticated
  with check (id = (select auth.uid()));
create policy profiles_own_update on public.profiles for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

alter table public.households enable row level security;
create policy households_member_select on public.households for select to authenticated
  using (private.is_household_member(id));
create policy households_creator_insert on public.households for insert to authenticated
  with check (created_by = (select auth.uid()));
create policy households_admin_update on public.households for update to authenticated
  using (private.has_household_role(id, array['owner','admin']))
  with check (private.has_household_role(id, array['owner','admin']));
create policy households_owner_delete on public.households for delete to authenticated
  using (private.has_household_role(id, array['owner']));

alter table public.household_members enable row level security;
create policy household_members_member_select on public.household_members for select to authenticated
  using (private.is_household_member(household_id));
create policy household_members_admin_insert on public.household_members for insert to authenticated
  with check (private.has_household_role(household_id, array['owner','admin']));
create policy household_members_admin_or_self_update on public.household_members for update to authenticated
  using (private.has_household_role(household_id, array['owner','admin']) or user_id = (select auth.uid()))
  with check (private.has_household_role(household_id, array['owner','admin']) or user_id = (select auth.uid()));
create policy household_members_admin_delete on public.household_members for delete to authenticated
  using (private.has_household_role(household_id, array['owner','admin']));

